import sys

def solve(queries):
    trie = {}
    def insert(word):
        node = trie
        for ch in word:
            if ch not in node: node[ch] = {}
            node = node[ch]
            if '_w' not in node: node['_w'] = []
            node['_w'].append(word)
    def suggest(prefix, k):
        node = trie
        for ch in prefix:
            if ch not in node: return []
            node = node[ch]
        return node.get('_w', [])[:k]
    out = []
    for q in queries:
        if q[0] == 1: insert(q[1])
        else:
            sug = suggest(q[1], q[2])
            out.append(str(len(sug)) + ("\n" + "\n".join(sug) if sug else ""))
    return "\n".join(out)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    q = int(lines[0])
    queries = []
    for i in range(1, q+1):
        parts = lines[i].split()
        t = int(parts[0])
        if t == 1: queries.append([t, parts[1]])
        else: queries.append([t, parts[1], int(parts[2])])
    print(solve(queries))

